const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(url,body){let r;try{r=await fetch(url,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})}catch(e){if(e instanceof TypeError)throw Error(`Cannot reach Sage at ${location.origin}. Check that Sage is running, then refresh this page.`);throw e}let x;try{x=await r.json()}catch{x={error:`Sage returned an unreadable response (${r.status}).`}}if(!r.ok)throw Error(x.error||'Request failed');return x}
function toast(t){let x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2600)}
function showForm(id){$('#'+id).classList.toggle('hidden')}
