$('#workshopForm').onsubmit=async e=>{e.preventDefault();try{let d=new FormData(e.target),image=$('#workshopPhoto').files[0],image_name='';if(image){let params=new URLSearchParams({name:image.name});if(d.get('project_id'))params.set('project_id',d.get('project_id'));let res=await fetch('/api/engineering/assets?'+params,{method:'POST',headers:{'Content-Type':image.type||'application/octet-stream'},body:image});let saved=await res.json();if(!res.ok)throw Error(saved.error||'Photo upload failed');image_name=saved.stored_name}await api('/api/workshop/log',{project_id:d.get('project_id'),note:d.get('note'),measurements:d.get('measurements'),image_name});e.target.reset();loadWorkshop();toast('Workshop entry saved')}catch(x){toast(x.message)}};
function calcFields(){let op=$('#calcOperation').value,fields={ohms_law:[['voltage_v','Voltage','V'],['current_a','Current','A'],['resistance_ohm','Resistance','Ω']],power:[['voltage_v','Voltage','V'],['current_a','Current','A']],moment:[['force_n','Force','N'],['arm_m','Perpendicular lever arm','m']],pressure_force:[['pressure_pa','Pressure','Pa'],['area_m2','Area','m²']],density:[['mass_kg','Mass','kg'],['volume_m3','Volume','m³']]};if(op==='convert'){$('#calcFields').innerHTML='<select name="category"><option value="length">Length</option><option value="mass">Mass</option><option value="pressure">Pressure</option><option value="force">Force</option><option value="temperature">Temperature</option></select><input name="value" type="number" step="any" placeholder="Value" required><select name="from_unit"></select><select name="to_unit"></select>';const options={length:['mm','m','cm','in','ft'],mass:['kg','g','lb'],pressure:['Pa','kPa','bar','psi'],force:['N','kN','lbf'],temperature:['C','F','K']};const refresh=()=>{let units=options[$('#calcFields [name=category]').value];['from_unit','to_unit'].forEach((name,i)=>{$('#calcFields [name="'+name+'"]').innerHTML=units.map(u=>`<option ${u===(i?'m':'mm')?'selected':''}>${u}</option>`).join('')})};$('#calcFields [name=category]').onchange=refresh;refresh();return}$('#calcFields').innerHTML=fields[op].map(([name,label,unit])=>`<label class="calcInput">${esc(label)} (${esc(unit)})<input name="${name}" type="number" step="any" ${op==='ohms_law'?'':'required'}></label>`).join('')+(op==='ohms_law'?'<p class="meta">Enter exactly two values; leave the third empty.</p>':'')}
$('#calcOperation').onchange=calcFields;calcFields();
$('#calcForm').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));let project_id=d.project_id;delete d.project_id;let operation=d.operation;delete d.operation;try{let out=await api('/api/engineering/calculate',{operation,values:d,project_id});let result=out.results?Object.entries(out.results).map(([k,v])=>`${esc(k)}: ${esc(v)} ${esc(out.units[k])}`).join('<br>'):`${esc(out.result)} ${esc(out.unit)}`;$('#calcResult').innerHTML=`<article class="card"><h3>Result · ${esc(out.formula)}</h3><p>${result}</p><p class="meta">Assumptions: ${out.assumptions.map(esc).join(' · ')}</p><p class="meta">Saved as ${esc(out.file)}</p></article>`}catch(x){toast(x.message)}};
