$('#assetForm').onsubmit=async e=>{e.preventDefault();let project=$('#assetProject').value;try{for(const file of $('#assetFiles').files){let params=new URLSearchParams({name:file.name});if(project)params.set('project_id',project);let r=await fetch('/api/engineering/assets?'+params,{method:'POST',headers:{'Content-Type':file.type||'application/octet-stream'},body:file}),out=await r.json();if(!r.ok)throw Error(out.error||'Import failed')}e.target.reset();await loadEngineeringOptions();loadAssets();toast('Engineering files imported')}catch(x){toast(x.message)}};
