$('#bomForm').onsubmit=async e=>{e.preventDefault();let d=new FormData(e.target),parts=String(d.get('parts')).split(/\r?\n/).map(line=>line.trim()).filter(Boolean).map(line=>{let [reference,part_number,description,quantity,unit,supplier,notes]=line.split('\t');return {reference,part_number,description,quantity,unit,supplier,notes}});try{let out=await api('/api/engineering/bom',{title:d.get('title'),project_id:d.get('project_id'),items:parts});$('#bomResult').innerHTML=`<article class="card"><h3>${esc(out.name)} · ${out.parts} parts</h3><p>Your BOM was saved locally and added to the CAD & BOM library.</p><p class="meta"><a href="${esc(out.url)}" download>Download CSV</a></p></article>`;e.target.reset();toast('BOM created')}catch(x){toast(x.message)}};
async function setTaskStatus(id,status){try{await api('/api/tasks/'+id,{status});await loadProjects();toast(status==='todo'?'Task unblocked and ready to do':'Task status updated')}catch(e){toast(e.message)}}
async function loadProjects(){let x=await api('/api/projects');$('#projectsList').innerHTML=x.length?x.map(p=>{let titles=new Map(p.tasks.map(t=>[t.id,t.title]));let tasks=p.tasks.map(t=>{let deps=[];try{deps=JSON.parse(t.depends_on||'[]')}catch{};let work=t.ai_work;return `<div class="task"><span>${esc(t.title)}</span><span class="pill ${t.status==='done'?'completed':t.status==='blocked'?'failed':t.status==='doing'?'running':''}">${esc(t.status)}</span>${t.status==='blocked'?`<button class="softBtn" onclick="setTaskStatus(${t.id},'todo')">Unblock task</button>`:''}${deps.length?`<span class="meta">Depends on: ${deps.map(id=>esc(titles.get(id)||'task')).join(', ')}</span>`:''}${work?`<details class="taskResult"><summary>${work.work_status==='complete'?'AI work result':work.work_status==='blocked'?'AI needs input':'AI work '+esc(work.job_status||'queued')}${work.summary?' · '+esc(work.summary):''}</summary>${work.deliverable?`<pre class="engineeringBody">${esc(work.deliverable)}</pre>`:''}${work.artifact?`<a href="/api/project-task-results/${work.job_id}/download" download>Download task deliverable</a>`:''}</details>`:''}</div>`}).join('');return `<article class="card"><h3>${esc(p.name)} <span class="pill">${esc(p.status)}</span></h3><p>${esc(p.description||'No description yet.')}</p><p class="meta">Next: ${esc(p.next_action||'Add a next action')} · Due ${esc(p.due_date||'not set')}</p><button class="softBtn" onclick="checkParts(${p.id})">Check BOM stock</button><form class="row addTask" data-id="${p.id}" style="margin-top:12px"><input name="title" placeholder="Add a task" required><button class="softBtn">Add task</button></form>${tasks}</article>`}).join(''):'<div class="empty">No projects yet. Sage will create and plan projects from your requests.</div>';document.querySelectorAll('.addTask').forEach(f=>f.onsubmit=async e=>{e.preventDefault();let title=new FormData(f).get('title');await api('/api/tasks',{project_id:f.dataset.id,title});loadProjects()})}
async function loadJobs(){let x=await api('/api/jobs');$('#jobsList').innerHTML=x.length?x.map(j=>{let detail=null;if(j.kind==='project_task'){try{detail=JSON.parse(j.result||'{}')}catch{}}return `<article class="card"><h3>${esc(j.title)} <span class="pill ${esc(j.status)}">${esc(j.status)}</span></h3><p>${esc(detail?.summary||j.checkpoint||j.prompt)}</p>${detail?.deliverable?`<details class="taskResult"><summary>View AI deliverable</summary><pre class="engineeringBody">${esc(detail.deliverable)}</pre></details>`:''}${detail?.artifact?`<p><a href="/api/project-task-results/${j.id}/download" download>Download task deliverable</a></p>`:''}<p class="meta">${esc(j.kind)} · Updated ${esc(j.updated_at)}</p>${['queued','running','paused'].includes(j.status)?`<div class="row" style="margin-top:10px">${j.status==='paused'?`<button class="softBtn" onclick="jobAction(${j.id},'resume')">Resume</button>`:`<button class="softBtn" onclick="jobAction(${j.id},'pause')">Pause</button>`}<button class="softBtn" onclick="jobAction(${j.id},'cancel')">Cancel</button></div>`:''}</article>`}).join(''):'<div class="empty">No background assignments.</div>'}
async function jobAction(id,action){await api('/api/jobs/'+id,{action});loadJobs()}
async function loadMemory(){let q=encodeURIComponent($('#memorySearch').value.trim()),[active,suggested]=await Promise.all([api('/api/memories?status=active'+(q?'&q='+q:'')),api('/api/memories?status=suggested'+(q?'&q='+q:''))]);$('#memoryList').innerHTML=active.length?active.map(m=>`<article class="card"><p>${esc(m.content)}</p><p class="meta">${esc(m.kind)} · ${esc(m.source)} · Confidence ${Math.round(Number(m.confidence||0)*100)}% · Used ${m.use_count||0} times <button class="softBtn" onclick="memoryStatus(${m.id},'archived')">Archive</button> <button class="softBtn" onclick="delMemory(${m.id})">Delete</button></p></article>`).join(''):'<div class="empty">No matching active memories.</div>';$('#memorySuggestions').innerHTML=suggested.length?suggested.map(m=>`<article class="card"><p>${esc(m.content)}</p><p class="meta">${esc(m.kind)} · ${esc(m.source)} · Suggested for review</p><button class="primary" onclick="memoryStatus(${m.id},'active')">Save memory</button> <button class="softBtn" onclick="memoryStatus(${m.id},'archived')">Dismiss</button></article>`).join(''):'<div class="empty">No memory suggestions to review.</div>'}
$('#memorySearch').oninput=()=>loadMemory();
async function memoryStatus(id,status){try{await api('/api/memories/'+id,{status});await loadMemory();toast(status==='active'?'Memory saved':'Suggestion dismissed')}catch(e){toast(e.message)}}
async function delMemory(id){await api('/api/memories/delete/'+id,{});loadMemory()}
async function loadNotes(){let x=await api('/api/notes'),names=new Set(x.map(n=>n.name)),edges=[];for(const n of x){for(const m of n.content.matchAll(/\[\[([^\]]+)\]\]/g)){if(names.has(m[1])&&m[1]!==n.name)edges.push([n.name,m[1]])}}$('#notesList').innerHTML=x.length?x.map(n=>`<article class="card"><h3>${esc(n.name)}</h3><p>${esc(n.content)}</p></article>`).join(''):'<div class="empty">Your local Obsidian-compatible vault is ready. Sage will add memories and links from conversations.</div>';drawGraph(x,edges)}
function drawGraph(notes,edges){const box=$('#graph');if(!notes.length){box.innerHTML='<span class="meta">Memories and projects will appear as Sage learns</span>';return}const w=Math.max(640,box.clientWidth||800),h=430,cx=w/2,cy=h/2,N=notes.length,counts=new Map(notes.map(n=>[n.name,0]));edges.forEach(([a,b])=>{counts.set(a,counts.get(a)+1);counts.set(b,counts.get(b)+1)});const nodes=notes.map((n,i)=>({name:n.name,x:cx+Math.cos(2*Math.PI*i/N)*Math.min(w*.37,h*.36),y:cy+Math.sin(2*Math.PI*i/N)*Math.min(w*.37,h*.36),r:Math.min(36,15+counts.get(n.name)*4)}));const byName=new Map(nodes.map(n=>[n.name,n]));let lines=edges.map(([a,b])=>{let u=byName.get(a),v=byName.get(b);return u&&v?`<line x1="${u.x}" y1="${u.y}" x2="${v.x}" y2="${v.y}" class="graphLine"/>`:''}).join('');let circles=nodes.map(n=>`<g class="graphNode" tabindex="0"><title>${esc(n.name)} · ${counts.get(n.name)} links</title><circle cx="${n.x}" cy="${n.y}" r="${n.r}"/><text x="${n.x}" y="${n.y+n.r+16}" text-anchor="middle">${esc(n.name.slice(0,24))}</text></g>`).join('');box.innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Obsidian note graph">${lines}${circles}</svg><div class="graphLegend">${notes.length} notes · ${edges.length} links · circle size reflects number of connections</div>`}
async function loadPlugins(){let x=await api('/api/plugins');$('#pluginsList').innerHTML=x.map(p=>`<article class="card"><h3>${esc(p.name)} <span class="pill">${esc(p.permission||'blocked')}</span></h3><p>${esc(p.description)}</p><p class="meta">v${esc(p.version||'?')} · ${esc(p.entrypoint||'metadata error')}</p><form class="row pluginRun" data-name="${esc(p.name)}" style="margin-top:12px"><input name="arguments" placeholder='JSON inputs, e.g. {"expression":"3*(8+2)"}'><label><input type="checkbox" name="dry_run"> Dry run</label><button class="softBtn">Run</button></form></article>`).join('')||'<div class="empty">No plugins installed.</div>';document.querySelectorAll('.pluginRun').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{let d=new FormData(f),args=JSON.parse(d.get('arguments')||'{}'),dry=d.has('dry_run');let first=await api('/api/plugins/run',{name:f.dataset.name,arguments:args,dry_run:dry});if(first.status==='pending_approval'&&confirm('This plugin requires approval. Run it now?')){let out=await api('/api/plugins/run',{name:f.dataset.name,arguments:args,approved:true});alert(JSON.stringify(out.result))}else if(first.result)alert(JSON.stringify(first.result));loadLogs()}catch(x){toast(x.message)}})}
async function loadLogs(){let x=await api('/api/actions');$('#logsList').innerHTML=x.length?x.map(a=>`<article class="card"><h3>${esc(a.plugin)} <span class="pill ${a.status==='completed'?'completed':''}">${esc(a.status)}</span></h3><p>Inputs: ${esc(a.arguments)}</p><p>${esc(a.result)}</p><p class="meta">${esc(a.created_at)}</p></article>`).join(''):'<div class="empty">No tool actions recorded.</div>'}
let outlookPollTimer=null;
async function loadOutlookPanel(){const host=$('#outlookCalendarPanel');if(!host)return;try{const s=await api('/api/outlook/status');if(s.pending){renderOutlookPending(s.pending);return}let data={events:[]};if(s.calendar_connected)data=await api('/api/outlook/events?days=7');let html='';if(s.ics_connected)html+=`<article class="card"><h3>Published Outlook calendar connected</h3><p>Sage reads the published ICS feed. This connection is read-only; the feed link is stored locally and never displayed again.</p><button class="softBtn" onclick="disconnectOutlookIcs()">Disconnect ICS feed</button></article>`;else html+=`<article class="card"><h3>Connect with an Outlook export link</h3><p>No Azure resource or app registration is needed for this read-only option. Paste your Outlook ICS link. Anyone who gets that link can view its published calendar details, so treat it like a password.</p><label>Outlook ICS publishing link<input id="outlookIcsUrl" type="url" placeholder="https://outlook.office365.com/owa/calendar/…/calendar.ics"></label><button class="primary" onclick="connectOutlookIcs()">Connect ICS feed</button><details><summary>How to get the link</summary><p>In Outlook on the web, open Settings → Calendar → Shared calendars → Publish a calendar. Choose the calendar and permission level, publish it, then copy the ICS link.</p><p>Your organization may disable calendar publishing. Sage validates links from Outlook publishing hosts only.</p></details></article>`;if(s.graph_connected)html+=`<article class="card"><h3>Microsoft Graph connected</h3><p>${esc(s.account||'Microsoft account')} · also enables event creation after approval.</p><button class="softBtn" onclick="disconnectOutlook()">Disconnect Graph</button></article>`;else html+=`<article class="card"><h3>Optional: connect Microsoft Graph</h3><p>Use Graph if you want Sage to create calendar events after your approval. App registration is not needed for the read-only ICS option.</p><label>Application (client) ID<input id="outlookClientId" placeholder="From your Microsoft app registration" value="${esc(localStorage.getItem('sageOutlookClientId')||'')}"></label><label>Tenant<input id="outlookTenant" value="${esc(s.tenant||'common')}"></label><button class="primary" onclick="connectOutlook()">Connect Graph</button><details><summary>Graph setup help</summary><p>Create an app registration in Microsoft Entra, enable public client flows, and add Microsoft Graph delegated permissions <code>User.Read</code> and <code>Calendars.ReadWrite</code>. See the Outlook setup guide.</p><p><a href="https://learn.microsoft.com/en-us/entra/identity-platform/scenario-desktop-acquire-token-device-code-flow" target="_blank" rel="noopener">Microsoft device sign-in guide</a></p></details></article>`;if(s.calendar_connected)html+=`<article class="card outlookCard"><div class="row spread"><div><h3>Upcoming agenda</h3><p>${esc(s.source==='ics'?'Published ICS feed':(s.account||'Microsoft Graph'))} · next 7 days</p></div></div>${data.events.length?data.events.map(e=>`<div class="outlookEvent"><b>${esc(e.subject)}</b><span>${esc(new Date(e.start).toLocaleString([], {weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}))}${e.is_all_day?' · all day':''}</span>${e.location?`<small>${esc(e.location)}</small>`:''}</div>`).join(''):'<p>No upcoming events in this range.</p>'}</article>`;host.innerHTML=html}catch(e){host.innerHTML=`<article class="card"><h3>Outlook calendar</h3><p>${esc(e.message)}</p><button class="softBtn" onclick="loadBriefing()">Retry</button></article>`}}
function renderOutlookPending(p){const host=$('#outlookCalendarPanel');host.innerHTML=`<article class="card"><h3>Finish connecting Outlook</h3><p>${esc(p.message||'Open Microsoft sign-in and enter this code:')}</p><h2 class="outlookCode">${esc(p.user_code)}</h2><a class="primary" href="${esc(p.verification_uri)}" target="_blank" rel="noopener">Open Microsoft sign-in</a><p class="meta">Sage will check sign-in status automatically. Code expires in about ${Math.ceil((p.expires_in||0)/60)} minutes.</p></article>`;if(!outlookPollTimer)outlookPollTimer=setInterval(async()=>{try{const result=await api('/api/outlook/poll',{});if(result.connected){clearInterval(outlookPollTimer);outlookPollTimer=null;toast('Outlook connected');loadBriefing()}else if(result.error){clearInterval(outlookPollTimer);outlookPollTimer=null;toast(result.error);loadOutlookPanel()}}catch(e){clearInterval(outlookPollTimer);outlookPollTimer=null;toast(e.message)}},5000)}
async function connectOutlook(){try{const client_id=$('#outlookClientId').value.trim(),tenant=$('#outlookTenant').value.trim()||'common';localStorage.setItem('sageOutlookClientId',client_id);const p=await api('/api/outlook/connect',{client_id,tenant});renderOutlookPending(p)}catch(e){toast(e.message)}}
async function disconnectOutlook(){if(!confirm('Disconnect Outlook from Sage and remove its saved sign-in token?'))return;try{await api('/api/outlook/disconnect',{});toast('Outlook disconnected');loadOutlookPanel()}catch(e){toast(e.message)}}
async function connectOutlookIcs(){try{await api('/api/outlook/ics/connect',{url:$('#outlookIcsUrl').value.trim()});toast('Outlook ICS feed connected');loadOutlookPanel()}catch(e){toast(e.message)}}
async function disconnectOutlookIcs(){if(!confirm('Remove the saved Outlook ICS publishing link from Sage?'))return;try{await api('/api/outlook/ics/disconnect',{});toast('Outlook ICS feed disconnected');loadOutlookPanel()}catch(e){toast(e.message)}}
async function loadBriefing(){let x=await api('/api/briefing'),items=[];items.push(`<article class="card"><h3>Today · ${esc(x.date)}</h3><p>${x.projects.length} active projects · ${x.overdue.length} overdue tasks</p></article>`);if(x.overdue.length)items.push(`<article class="card"><h3>Needs attention</h3>${x.overdue.map(t=>`<p>${esc(t.title)} · due ${esc(t.due_date)}</p>`).join('')}</article>`);if(x.projects.length)items.push(...x.projects.map(p=>`<article class="card"><h3>${esc(p.name)}</h3><p>${esc(p.next_action||'Choose the next action')}</p>${p.tasks.map(t=>`<p class="meta">Next task: ${esc(t.title)}</p>`).join('')}</article>`));if(x.recent_jobs.length)items.push(`<article class="card"><h3>Recently completed</h3>${x.recent_jobs.map(j=>`<p>${esc(j.title)} <span class="meta">${esc(j.updated_at)}</span></p>`).join('')}</article>`);if(x.recent_learning.length)items.push(`<article class="card"><h3>Recent learning</h3>${x.recent_learning.map(m=>`<p>${esc(m.content)}</p>`).join('')}</article>`);$('#briefingList').innerHTML=items.join('');await loadOutlookPanel()}
async function loadCheckins(){let x=await api('/api/checkins');$('#checkinsList').innerHTML=x.length?x.map(c=>`<article class="card"><h3>${esc(c.project.name)}</h3><p>${c.reasons.map(esc).join(' · ')}</p><p class="meta">Next action: ${esc(c.project.next_action||'not set')}</p></article>`).join(''):'<div class="empty">No project check-ins are due right now.</div>'}
async function loadFocus(){let [x,p]=await Promise.all([api('/api/focus'),api('/api/projects')]);$('#focusBadge').classList.toggle('hidden',!x.enabled);$('#focusPanel').innerHTML=x.enabled?`<h3>Focus in progress</h3><p>${esc(x.goal)}</p><p class="meta">Ends ${esc(x.ends_at)} ${x.project_id?'· Linked to a project':''}</p>`:'<h3>No active focus session</h3><p>Choose a goal and duration to start one.</p>';$('#focusForm').classList.toggle('hidden',!!x.enabled);$('#focusStop').classList.toggle('hidden',!x.enabled);$('#focusProject').innerHTML='<option value="">No linked project</option>'+p.map(z=>`<option value="${z.id}">${esc(z.name)}</option>`).join('')}
async function loadResearch(){let x=await api('/api/research');$('#researchList').innerHTML=x.length?x.map(j=>jobCard(j)).join(''):'<div class="empty">No research reports yet.</div>';loadWatchlist()}
async function loadLearner(){let x=await api('/api/learner');$('#learnerList').innerHTML=x.length?x.map(j=>jobCard(j)).join(''):'<div class="empty">No learning tasks yet. Clear factual uncertainty or a correction may create a sourced task for review here.</div>'}
function jobCard(j){let result=j.result||j.checkpoint||j.prompt,z={};try{z=JSON.parse(j.result);result=z.summary||j.checkpoint||j.prompt}catch{}let sources=(z.sources||[]).map(s=>{try{let u=new URL(s.url);return u.protocol==='https:'?`<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${esc(s.title||u.hostname)}</a>`:esc(s.title||s.url)}catch{return esc(s.title||s.url||'')}}).join(' · ');let reason=z.origin==='conversation_gap'?`<p><strong>Why this was queued:</strong> ${esc(z.reason||'Sage identified a knowledge gap.')}</p><p class="meta">Conversation evidence: “${esc(z.evidence||'')}”</p>`:'';return `<article class="card"><h3>${esc(j.title)} <span class="pill ${esc(j.status)}">${esc(j.status)}</span></h3>${reason}<p>${esc(result)}</p>${sources?`<p class="meta">Sources: ${sources}</p>`:''}<p class="meta">${esc(j.checkpoint||j.kind)} · ${esc(j.updated_at)}</p>${['queued','running','paused'].includes(j.status)?`<button class="softBtn" onclick="jobAction(${j.id},'${j.status==='paused'?'resume':'pause'}')">${j.status==='paused'?'Resume':'Pause'}</button> <button class="softBtn" onclick="jobAction(${j.id},'cancel')">Cancel</button>`:''}</article>`}
async function loadWatchlist(){let x=await api('/api/watchlist');$('#watchlist').innerHTML=x.length?x.map(w=>`<article class="card watchItem"><span>${esc(w.topic)} <span class="pill">Every ${w.interval_days} day(s)</span></span><button class="softBtn" onclick="deleteWatch(${w.id})">Remove</button><p class="meta">${w.last_checked?'Last checked '+esc(w.last_checked):'Queued on the next idle window'}</p></article>`).join(''):'<div class="empty">No topics watched yet.</div>'}
async function deleteWatch(id){await api('/api/watchlist/delete/'+id,{});loadWatchlist()}
async function loadPluginRequests(){let x=await api('/api/plugin-requests');$('#pluginRequests').innerHTML=x.length?x.map(r=>`<article class="card"><h3>${esc(r.capability)}</h3><p>${esc(r.reason)}</p><p class="meta">Recognized from a conversation · ${esc(r.created_at)}</p><button class="softBtn" onclick="pluginRequest(${r.id},'create-starter')">Create safe starter</button> <button class="softBtn" onclick="pluginRequest(${r.id},'dismiss')">Dismiss</button></article>`).join(''):'<div class="empty">No plugin requests detected from conversations.</div>'}
async function pluginRequest(id,action){try{let x=await api('/api/plugin-requests/'+id,{action});if(x.name)toast('Starter plugin '+x.name+' created; review its code before using it.');loadPlugins()}catch(e){toast(e.message)}}
async function loadEngineeringOptions(){let [projects,assets]=await Promise.all([api('/api/projects'),api('/api/engineering/assets')]);const projectOptions='<option value="">No linked project</option>'+projects.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');['workshopProject','calcProject','engineeringProject','assetProject','bomProject','codeProjectProject'].forEach(id=>{let el=$('#'+id);if(el){let old=el.value;el.innerHTML=projectOptions;el.value=old}});$('#engineeringAssets').innerHTML=assets.map(a=>`<option value="${a.id}">${esc(a.name)} · ${esc(a.extension)}</option>`).join('')}
async function loadWorkshop(){await loadEngineeringOptions();let x=await api('/api/workshop/log');$('#workshopList').innerHTML=x.length?x.map(e=>`<article class="card"><h3>Entry ${e.id} <span class="pill">${esc(e.created_at)}</span></h3><p>${esc(e.note)}</p>${e.measurements?`<p class="measurements">${esc(e.measurements)}</p>`:''}${e.image_name?`<img class="workshopImage" src="/api/workshop/photos/${encodeURIComponent(e.image_name)}" alt="Workshop log photo">`:''}</article>`).join(''):'<div class="empty">Your workshop notebook is ready. Log a build step, observation, measurement, or photo.</div>'}
async function loadAssets(){await loadEngineeringOptions();let x=await api('/api/engineering/assets');$('#assetList').innerHTML=x.length?x.map(a=>`<article class="card"><h3>${esc(a.name)} <span class="pill">${esc(a.extension)}</span></h3><p>${esc(JSON.stringify(a.metadata||{}))}</p><p class="meta">${(a.size_bytes/1024).toFixed(1)} KB · SHA-256 ${esc(a.sha256||'')} · ${esc(a.created_at)} · <a href="/api/engineering/assets/${a.id}/download" download>Download</a></p></article>`).join(''):'<div class="empty">No CAD, electronics, BOM, or workshop images imported yet.</div>'}
async function loadEngineeringDocs(){await loadEngineeringOptions();let x=await api('/api/engineering/documents');$('#engineeringDocs').innerHTML=x.length?x.map(d=>`<article class="card"><h3>${esc(d.title)} <span class="pill">${esc(d.kind.replace('_',' '))}</span></h3><p class="meta">${esc(d.status)} · ${esc(d.created_at)} · <a href="/api/engineering/documents/${d.id}/download" download>Download Markdown report</a></p><details><summary>Read generated document</summary><pre class="engineeringBody">${esc(d.body)}</pre></details>${d.results?.length?`<h4>Recorded test results</h4>${d.results.map(r=>`<p class="meta">${esc(r.outcome)} · ${esc(r.created_at)} · ${esc(r.notes)} ${esc(r.measurements)}</p>`).join('')}`:''}${d.kind==='test_plan'?`<button class="softBtn" onclick="compareTest(${d.id})">Compare test runs</button><div id="testCompare${d.id}"></div><form class="testResultForm" data-id="${d.id}"><select name="outcome"><option value="passed">Passed</option><option value="failed">Failed</option><option value="blocked">Blocked</option><option value="not_run">Not run</option></select><textarea name="measurements" placeholder="Measured results"></textarea><textarea name="notes" placeholder="Observations or issues"></textarea><button class="softBtn">Record test result</button></form>`:''}</article>`).join(''):'<div class="empty">No plans or reviews yet. Describe a design or verification goal above and Sage will draft a report when idle.</div>';document.querySelectorAll('.testResultForm').forEach(f=>f.onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(f));try{await api('/api/engineering/documents/'+f.dataset.id+'/results',d);loadEngineeringDocs();toast('Test result recorded')}catch(x){toast(x.message)}})}
async function loadCodeProjects(){await loadEngineeringOptions();let x=await api('/api/engineering/code-projects');$('#codeProjects').innerHTML=x.length?x.map(p=>`<article class="card"><h3>${esc(p.name)} <span class="pill">${esc(p.status)}</span></h3><p>${esc(p.summary)}</p><p class="meta">${p.project_id?'Linked to project '+p.project_id+' · ':''}Files: ${p.files.map(f=>esc(f.filename)).join(', ')}</p><details class="codeProjectFiles" data-id="${p.id}"><summary>Inspect and edit generated files</summary><div class="projectCode"></div></details><div class="row" style="margin-top:12px"><button class="softBtn" onclick="runProjectTests(${p.id})">Run unit tests</button></div></article>`).join(''):'<div class="empty">No engineering code projects yet.</div>';document.querySelectorAll('.codeProjectFiles').forEach(d=>d.ontoggle=async()=>{if(!d.open||d.dataset.loaded)return;d.dataset.loaded='1';let files=await api('/api/engineering/code-projects/'+d.dataset.id+'/files');d.querySelector('.projectCode').innerHTML=files.map(f=>`<form class="projectCodeEdit" data-project="${d.dataset.id}" data-file="${esc(f.filename)}"><h4>${esc(f.filename)}</h4><textarea name="content" spellcheck="false">${esc(f.content)}</textarea><button class="softBtn">Save ${esc(f.filename)}</button></form>`).join('');d.querySelectorAll('.projectCodeEdit').forEach(form=>form.onsubmit=async e=>{e.preventDefault();try{await api('/api/engineering/code-projects/'+form.dataset.project+'/files/'+encodeURIComponent(form.dataset.file),{content:new FormData(form).get('content')});toast('Saved '+form.dataset.file)}catch(x){toast(x.message)}})})}
async function runProjectTests(id){if(!confirm('Review the generated files first. Running tests executes Python code with this account’s permissions, and is not a system sandbox. Run the project tests?'))return;try{let first=await api('/api/engineering/code-projects/'+id+'/tests',{approved:false});if(first.status==='pending_approval'){let out=await api('/api/engineering/code-projects/'+id+'/tests',{approved:true});$('#codeProjects').insertAdjacentHTML('afterbegin',`<article class="card testOutput"><h3>Test run · ${esc(out.status)}</h3><pre class="engineeringBody">${esc(out.output||out.message||'No test files found.')}</pre><p class="meta">${esc(out.warning||'')}</p></article>`);toast('Test run '+out.status)}}catch(e){toast(e.message)}}
async function loadPage(p){({bench:loadBench,measurements:loadMeasurements,decisions:loadDecisions,'session-review':loadSummaries,backups:loadBackups,system:loadSystemHealth,briefing:loadBriefing,checkins:loadCheckins,focus:loadFocus,projects:loadProjects,workshop:loadWorkshop,'notebook-search':()=>{$('#notebookResults').innerHTML=''},inventory:loadInventory,troubleshooting:loadTroubleshooting,versions:loadVersions,handoffs:loadHandoffs,failures:loadFailures,tailscale:loadTailscale,calculations:loadEngineeringOptions,verification:loadEngineeringDocs,assets:loadAssets,bom:loadEngineeringOptions,'code-lab':loadCodeProjects,jobs:loadJobs,research:loadResearch,learner:loadLearner,memory:loadMemory,knowledge:loadNotes,plugins:loadPlugins,logs:loadLogs})[p]?.()}
async function loadToolApprovals(){try{let x=await api('/api/tool-approvals');$('#toolApprovals').innerHTML=x.map(a=>`<article class="card approvalCard"><h3>Approval needed · ${esc(a.tool_name)}</h3><p>Sage selected this tool for your request. Review its inputs before it runs.</p><pre class="engineeringBody">${esc(JSON.stringify(a.arguments,null,2))}</pre><p class="meta">Requested ${esc(a.created_at)}</p><div class="row"><button class="primary" onclick="resolveToolApproval(${a.id},true)">Approve and run</button><button class="softBtn" onclick="resolveToolApproval(${a.id},false)">Decline</button></div></article>`).join('')}catch{}}
async function resolveToolApproval(id,approved){try{let x=await api('/api/tool-approvals/'+id,{approved});$('#toolApprovals').querySelector(`[onclick^="resolveToolApproval(${id},"]`)?.closest('.approvalCard')?.remove();bubble('assistant',x.answer);loadToolApprovals();loadLogs()}catch(e){toast(e.message)}}
async function loadPlugins(){let [x,tools]=await Promise.all([api('/api/plugins'),api('/api/tools')]);$('#aiTools').innerHTML=tools.map(t=>`<article class="card"><h3>${esc(t.name)} <span class="pill ${t.permission==='confirm'?'pending_approval':''}">${esc(t.permission==='confirm'?'approval required':t.permission)}</span></h3><p>${esc(t.description)}</p></article>`).join('')||'<div class="empty">No tools are available to the model.</div>';$('#pluginsList').innerHTML=x.map(p=>`<article class="card"><h3>${esc(p.name)} <span class="pill">${esc(p.permission||'blocked')}</span></h3><p>${esc(p.description)}</p><p class="meta">v${esc(p.version||'?')} · ${esc(p.entrypoint||'metadata error')}</p><form class="row pluginRun" data-name="${esc(p.name)}" style="margin-top:12px"><input name="arguments" placeholder='JSON inputs, e.g. {"expression":"3*(8+2)"}'><label><input type="checkbox" name="dry_run"> Dry run</label><button class="softBtn">Run</button></form></article>`).join('')||'<div class="empty">No plugins installed.</div>';loadPluginRequests();document.querySelectorAll('.pluginRun').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{let d=new FormData(f),args=JSON.parse(d.get('arguments')||'{}'),dry=d.has('dry_run');let first=await api('/api/plugins/run',{name:f.dataset.name,arguments:args,dry_run:dry});if(first.status==='pending_approval'&&confirm('This plugin requires approval. Run it now?')){let out=await api('/api/plugins/run',{name:f.dataset.name,arguments:args,approved:true});alert(JSON.stringify(out.result))}else if(first.result)alert(JSON.stringify(first.result));loadLogs()}catch(x){toast(x.message)}})}
async function status(){try{let x=await api('/api/status'),o=x.ollama;$('#statusDot').classList.toggle('on',o.online&&o.installed);$('#statusText').textContent=o.online?(o.installed?'Ollama ready':'Model missing'):'Ollama offline';$('#modelLabel').textContent=x.model;wakePhrase=(x.wake_word||'sage').toLowerCase()}catch{}}
loadChat();status();pollNotifications();scheduleDailyBriefing();setInterval(status,15000);setInterval(pollNotifications,15000);setInterval(scheduleDailyBriefing,60000);

async function projectOptions(ids){let p=await api('/api/projects'),html='<option value="">No linked project</option>'+p.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');for(const id of ids){let e=$('#'+id);if(e){let old=e.value;e.innerHTML=html;e.value=old}}return p}
async function loadInventory(){await projectOptions(['inventoryProject']);let x=await api('/api/inventory');$('#inventoryList').innerHTML=x.length?x.map(i=>`<article class="card"><h3>${esc(i.name)} <span class="pill ${i.quantity<=i.reorder_level?'failed':''}">${i.quantity<=i.reorder_level?'Low stock':'In stock'} · ${esc(i.quantity)} ${esc(i.unit)}</span></h3><p>${esc(i.description||i.part_number||'')}</p><p class="meta">${i.part_number?'Part '+esc(i.part_number)+' · ':''}${esc(i.location||'Location not set')} · ${esc(i.supplier||'No supplier')}${i.project_id?' · Project '+i.project_id:''} · Alert below ${esc(i.reorder_level)}</p><form class="row stockMove" data-id="${i.id}"><input name="delta" type="number" step="any" placeholder="+/- stock" required><input name="reason" placeholder="Reason (used, received, correction)" required><button class="softBtn">Adjust stock</button></form>${i.movements?.length?`<details><summary>Stock history</summary>${i.movements.map(m=>`<p class="meta">${m.delta>0?'+':''}${m.delta} · ${esc(m.reason)} · ${esc(m.created_at)}</p>`).join('')}</details>`:''}</article>`).join(''):'<div class="empty">No inventory yet. Add parts you want Sage to track.</div>';document.querySelectorAll('.stockMove').forEach(f=>f.onsubmit=async e=>{e.preventDefault();let v=Object.fromEntries(new FormData(f));try{await api(`/api/inventory/${f.dataset.id}/move`,v);loadInventory();toast('Stock updated')}catch(x){toast(x.message)}})}
async function loadTroubleshooting(){await projectOptions(['troubleshootProject']);let x=await api('/api/troubleshooting');$('#troubleshootingList').innerHTML=x.length?x.map(t=>{let s=t.sessions?.[0],step=t.steps[Math.min(s?.step_index||0,t.steps.length-1)];return `<article class="card"><h3>${esc(t.title)}</h3><p><b>Symptom:</b> ${esc(t.symptom)}</p><ol>${t.steps.map((z,i)=>`<li class="${s&&s.step_index===i?'activeStep':''}">${esc(z)}</li>`).join('')}</ol>${s?`<p class="pill">${esc(s.status)} · Step ${(s.step_index||0)+1} of ${t.steps.length}: ${esc(step)}</p><textarea id="troubleNotes${s.id}" placeholder="Record readings or observations">${esc(s.notes)}</textarea><div class="row"><button class="softBtn" onclick="troubleAction(${s.id},'next')">Step passed · next</button><button class="softBtn" onclick="troubleAction(${s.id},'unresolved')">Still unresolved</button><button class="primary" onclick="troubleAction(${s.id},'resolved')">Resolved</button></div>`:`<button class="softBtn" onclick="startTrouble(${t.id})">Start guided check</button>`}</article>`}).join(''):'<div class="empty">No troubleshooting guides yet.</div>'}
async function startTrouble(id){await api(`/api/troubleshooting/${id}/start`,{});loadTroubleshooting()}
async function troubleAction(id,action){try{await api(`/api/troubleshooting/sessions/${id}`,{action,notes:$(`#troubleNotes${id}`)?.value||''});loadTroubleshooting()}catch(e){toast(e.message)}}
async function loadVersions(){let [a,v]=await Promise.all([api('/api/engineering/assets'),api('/api/engineering/versions')]);$('#versionAsset').innerHTML='<option value="">Choose an imported design file</option>'+a.filter(z=>!['.jpg','.jpeg','.png','.webp'].includes(z.extension)).map(z=>`<option value="${z.id}">${esc(z.name)} · ${esc(z.created_at)}</option>`).join('');$('#versionsList').innerHTML=v.length?v.map(z=>`<article class="card"><h3>${esc(z.name)} <span class="pill">v${z.version}</span></h3><p>${esc(z.notes||'No change notes')}</p><p class="meta">${esc(z.project_name||'Unlinked project')} · ${esc(z.created_at)} · SHA-256 ${esc(z.sha256)} · <a href="/api/engineering/versions/${z.id}/download" download>Download snapshot</a> · <button class="softBtn" onclick="compareDesign(${z.id})">What changed?</button></p><div id="designCompare${z.id}"></div></article>`).join(''):'<div class="empty">No design snapshots saved yet.</div>'}
async function loadHandoffs(){let [p,h]=await Promise.all([projectOptions(['handoffProject']),api('/api/handoffs')]);$('#handoffsList').innerHTML=h.length?h.map(d=>`<article class="card"><h3>${esc(d.title)}</h3><p class="meta">${esc(d.created_at)} · <a href="/api/engineering/documents/${d.id}/download" download>Download handoff sheet</a></p></article>`).join(''):'<div class="empty">Generate a handoff sheet when you want a compact project restart point.</div>'}
async function loadFailures(){await projectOptions(['failureProject']);let x=await api('/api/failures');$('#failuresList').innerHTML=x.length?x.map(f=>`<article class="card"><h3>${esc(f.title)}</h3><p><b>Symptom:</b> ${esc(f.symptom)}</p><p><b>Cause:</b> ${esc(f.cause||'Not determined')}</p><p><b>Fix:</b> ${esc(f.fix||'Not recorded')}</p><p><b>Lesson:</b> ${esc(f.lesson||'Not recorded')}</p><p class="meta">${esc(f.project_name||'Unlinked project')} · ${esc(f.created_at)}</p></article>`).join(''):'<div class="empty">No failures recorded. Recording unknown causes is useful too.</div>'}
async function loadTailscale(){let x=await api('/api/tailscale');$('#tailscaleCommand').textContent=x.command;$('#tailscaleStatus').innerHTML=`<article class="card"><h3>${x.installed?'Tailscale installed':'Tailscale CLI not found'} <span class="pill ${x.running?'completed':''}">${x.running?'Connected':'Not connected'}</span></h3><p>${x.hostname?'Device: '+esc(x.hostname):'Install and sign into Tailscale on the computer running Sage.'}</p>${x.serve_status?`<details><summary>Serve status</summary><pre class="engineeringBody">${esc(x.serve_status)}</pre></details>`:''}</article>`}
$('#inventoryForm').onsubmit=async e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target));try{await api('/api/inventory',v);e.target.reset();loadInventory();toast('Part added to inventory')}catch(x){toast(x.message)}};
$('#notebookSearchForm').onsubmit=async e=>{e.preventDefault();let q=new FormData(e.target).get('q');try{let x=await api('/api/workshop/search?q='+encodeURIComponent(q));$('#notebookResults').innerHTML=x.results.length?x.results.map(r=>`<article class="card"><h3>${esc(r.title)} <span class="pill">${esc(r.type.replace('_',' '))}</span></h3><p>${esc(r.body).slice(0,1800)}</p><p class="meta">${esc(r.created_at)}</p></article>`).join(''):'<div class="empty">No matching workshop records found.</div>'}catch(x){toast(x.message)}};
$('#troubleshootForm').onsubmit=async e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target));v.steps=v.steps.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);try{await api('/api/troubleshooting',v);e.target.reset();loadTroubleshooting();toast('Troubleshooting guide saved')}catch(x){toast(x.message)}};
$('#versionForm').onsubmit=async e=>{e.preventDefault();try{let x=await api('/api/engineering/versions',Object.fromEntries(new FormData(e.target)));e.target.reset();loadVersions();toast('Saved design snapshot v'+x.version)}catch(x){toast(x.message)}};
$('#handoffForm').onsubmit=async e=>{e.preventDefault();try{let pid=new FormData(e.target).get('project_id'),x=await api(`/api/projects/${pid}/handoff`,{});$('#handoffsList').insertAdjacentHTML('afterbegin',`<article class="card"><h3>${esc(x.title)}</h3><details open><summary>Preview handoff</summary><pre class="engineeringBody">${esc(x.content)}</pre></details><p><a href="${esc(x.url)}" download>Download Markdown</a> · Saved in Obsidian vault</p></article>`);toast('Handoff sheet generated')}catch(x){toast(x.message)}};
$('#failureForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/failures',Object.fromEntries(new FormData(e.target)));e.target.reset();loadFailures();toast('Failure and lesson saved')}catch(x){toast(x.message)}};
$('#copyTailscale').onclick=async()=>{try{await navigator.clipboard.writeText($('#tailscaleCommand').textContent);toast('Tailscale command copied')}catch{toast('Could not access clipboard')}};
async function fillProjectSelectors(){let p=await api('/api/projects');let html='<option value="">No linked project</option>'+p.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');for(let id of ['chatProject','benchProject','measurementProject','decisionProject','summaryProject']){let el=$('#'+id);if(!el)continue;let old=localStorage.getItem('sage-'+id)||el.value;el.innerHTML=(id==='chatProject'?'<option value="">No active project</option>':id==='summaryProject'?'<option value="">Whole session</option>':'<option value="">No linked project</option>')+p.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');el.value=old;if(el.value!==old)el.value='';el.onchange=()=>localStorage.setItem('sage-'+id,el.value)}}
async function loadBench(){await fillProjectSelectors();let id=$('#benchProject').value;if(!id){$('#benchContext').innerHTML='<div class="empty">Choose a project to see its current status.</div>';return}let p=(await api('/api/projects')).find(x=>String(x.id)===id);let stock=await api(`/api/projects/${id}/parts-status`);$('#benchContext').innerHTML=`<article class="card"><h3>${esc(p.name)}</h3><p>${esc(p.description||'No description')}</p><p><b>Next action:</b> ${esc(p.next_action||'Not set')}</p><p>${p.tasks.filter(t=>t.status!=='done').slice(0,6).map(t=>`• ${esc(t.title)} (${esc(t.status)})`).join('<br>')||'No open tasks'}</p><p>${stock.shortages.length} BOM shortages · ${stock.parts.length} listed parts</p></article>`}
async function loadMeasurements(){await fillProjectSelectors();let x=await api('/api/measurement-templates');$('#measurementList').innerHTML=x.map(t=>`<article class="card"><h3>${esc(t.title)}</h3><p>${esc(t.description||'Repeatable measurements')}</p><form class="measurementRun" data-id="${t.id}">${t.fields.map(f=>`<label>${esc(f.name)} ${f.unit?`(${esc(f.unit)})`:''}<input name="${esc(f.name)}" placeholder="Value${f.target?` · target ${esc(f.target)}`:''}" required></label>`).join('')}<textarea name="notes" placeholder="Run notes"></textarea><button class="primary">Save measurement run</button></form><details><summary>Recent runs (${t.runs.length})</summary>${t.runs.map(r=>`<p>${esc(r.created_at)} · ${esc(r.notes)}</p><small>${esc(JSON.stringify(r.values||{}))}</small>`).join('')}</details></article>`).join('')||'<div class="empty">Create your first template.</div>';document.querySelectorAll('.measurementRun').forEach(f=>f.onsubmit=async e=>{e.preventDefault();let data=Object.fromEntries(new FormData(f)),notes=data.notes;delete data.notes;try{await api(`/api/measurement-templates/${f.dataset.id}/runs`,{values:data,notes,project_id:$('#measurementProject').value||null});loadMeasurements();toast('Measurement run saved')}catch(x){toast(x.message)}})}
async function loadDecisions(){await fillProjectSelectors();let x=await api('/api/decisions');$('#decisionList').innerHTML=x.map(d=>`<article class="card"><h3>${esc(d.title)}</h3><p><b>Decision:</b> ${esc(d.decision)}</p><p><b>Alternatives:</b> ${esc(d.alternatives||'Not recorded')}</p><p><b>Rationale:</b> ${esc(d.rationale||'Not recorded')}</p><p class="meta">${esc(d.project_name||'Unlinked')} · ${esc(d.created_at)}</p></article>`).join('')||'<div class="empty">No decisions recorded yet.</div>'}
async function loadSummaries(){await fillProjectSelectors();let x=await api('/api/session-summaries');$('#summaryList').innerHTML=x.map(s=>`<article class="card"><h3>${esc(s.title)} <span class="pill">${esc(s.status)}</span></h3>${s.content?`<pre class="engineeringBody">${esc(s.content)}</pre>`:''}${s.status==='pending_review'?`<button class="primary" onclick="summaryAction(${s.id},'approve')">Approve & save to Obsidian</button> <button class="softBtn" onclick="summaryAction(${s.id},'discard')">Discard</button>`:''}<p class="meta">${esc(s.updated_at)}</p></article>`).join('')||'<div class="empty">No session summaries yet.</div>'}
async function summaryAction(id,action){try{await api(`/api/session-summaries/${id}`,{action});loadSummaries();toast(action==='approve'?'Summary saved':'Draft discarded')}catch(x){toast(x.message)}}
async function loadBackups(){let x=await api('/api/backups');$('#backupList').innerHTML=x.map(b=>`<article class="card"><h3>${esc(b.name)}</h3><p class="meta">${esc(b.created_at)} · ${(b.size/1048576).toFixed(2)} MB</p><button class="softBtn" onclick="restoreBackup('${esc(b.name)}')">Restore this backup</button></article>`).join('')||'<div class="empty">No backups saved yet.</div>'}
async function restoreBackup(name){if(!confirm(`Restore ${name}? Sage will replace its current database, vault, workspace, engineering files, and imports with this backup.`))return;try{let x=await api(`/api/backups/${encodeURIComponent(name)}/restore`,{confirmed:true});toast(x.message);loadBackups()}catch(e){toast(e.message)}}
$('#measurementTemplateForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),fields=String(f.get('fields')).split(/\r?\n/).map(line=>{let [name,unit='',target='',tolerance='']=line.split('|').map(x=>x.trim());return{name,unit,target,tolerance}}).filter(x=>x.name);try{await api('/api/measurement-templates',{title:f.get('title'),project_id:f.get('project_id')||null,fields});e.target.reset();loadMeasurements();toast('Measurement template saved')}catch(x){toast(x.message)}};
$('#decisionForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/decisions',Object.fromEntries(new FormData(e.target)));e.target.reset();loadDecisions();toast('Decision recorded')}catch(x){toast(x.message)}};
$('#draftSummary').onclick=async()=>{try{let x=await api('/api/session-summaries/draft',{project_id:$('#summaryProject').value||null});toast(`Summary queued as background job ${x.job_id}`);loadSummaries()}catch(e){toast(e.message)}};
$('#createBackup').onclick=async()=>{try{let x=await api('/api/backups',{});toast('Backup created');loadBackups()}catch(e){toast(e.message)}};
$('#benchProject').onchange=loadBench;$('#benchSave').onclick=async()=>{let note=$('#benchNote').value.trim(),pid=$('#benchProject').value;if(!pid||!note){toast('Choose a project and dictate or enter a note');return}try{await api('/api/workshop/log',{project_id:pid,note});$('#benchNote').value='';toast('Bench note saved')}catch(e){toast(e.message)}};
$('#benchSummary').onclick=async()=>{let pid=$('#benchProject').value;if(!pid){toast('Choose the active project first');return}try{let x=await api('/api/session-summaries/draft',{project_id:pid,title:'Bench session summary'});toast(`Summary queued as background job ${x.job_id}`)}catch(e){toast(e.message)}};
$('#benchDictate').onclick=()=>benchRecognition?stopDictation('bench'):startDictation('bench');
fillProjectSelectors();
setInterval(()=>{if($('#page-projects')?.classList.contains('active'))loadProjects().catch(()=>{});if($('#page-jobs')?.classList.contains('active'))loadJobs().catch(()=>{})},15000);
async function checkParts(id){try{let x=await api(`/api/projects/${id}/parts-status`);let body=x.parts.length?x.parts.map(p=>`<p>${esc(p.name)} · ${esc(p.on_hand)} / ${esc(p.required)} ${esc(p.unit)}${p.shortage?` · <b>short ${esc(p.shortage)}</b>`:''}</p>`).join(''):'<p>No linked BOM files.</p>';let card=document.createElement('article');card.className='card';card.innerHTML=`<h3>Project stock check</h3>${body}`;$('#projectsList').prepend(card)}catch(e){toast(e.message)}}
async function compareDesign(id){try{let x=await api(`/api/engineering/versions/${id}/compare`),target=$(`#designCompare${id}`);target.innerHTML=`<p>${esc(x.summary||'Comparison complete')}</p>${x.previous?`<p class="meta">v${x.previous.version} → v${x.current.version}</p>`:''}${x.diff?`<pre class="engineeringBody">${esc(x.diff)}</pre>`:''}`}catch(e){toast(e.message)}}
async function compareTest(id){try{let x=await api(`/api/engineering/documents/${id}/compare`);$(`#testCompare${id}`).innerHTML=`<p>${esc(x.summary||JSON.stringify(x.changed||{}))}</p><pre class="engineeringBody">${esc(JSON.stringify(x.changed||x.runs,null,2))}</pre>`}catch(e){toast(e.message)}}
